SELECT c.NAME AS Name1, w.YEAR, w.NUST, w.E, w.B, z([don])+z([podm])+z([pech])+z([kuzn])+z([ural])+z([bashk])+z([ekib])+z([karag])+z([kan])+z([irkut])+z([hak])+z([tuv])+z([bur])+z([chit])+z([yakut])+z([amur])+z([prim])+z([urg])+z([luch])+z([mag])+z([sah]) AS ugol, w!DON/IIf(n.don>0,N!DON,0.699) AS don, w.podm/IIf(n.podm>0,N.podm,0.274) AS podm, z([vork])+z([int]) AS pech, d.vork/IIf(n.vork>0,N.vork,0.677) AS Vork, d.int/IIf(n.int>0,N.int,0.532) AS [int], IIf(w.year<=2000,w.kuzn/IIf(n.kuzn>0,n.kuzn,0.777),z([kuznss])+z([kuzngd])+z([kuznt])+z([kuznun])) AS kuzn, IIf(W!YEAR=2000,0,d!kuznss/0.803) AS kuznss, IIf(W!YEAR=2000,0,d!kuzngd/0.718) AS kuzngd, IIf(W!YEAR=2000,0,d!kuznun/0.769) AS kuznun, IIf(W!YEAR=2000,0,d!kuznt/0.81) AS kuznt, z([sver])+z([chel])+z([kizel]) AS ural, d!sver/IIf(n.sver>0,N!sver,0.316) AS sver, d!chel/IIf(n.chel>0,N!chel,0.422) AS chel, d!kizel/IIf(n.kizel>0,N!kizel,0.624) AS kizel, W!bashk/IIf(n.bashk>0,N!bashk,0.29) AS bashk, W!ekib/IIf(n.ekib>0,N!ekib,0.551) AS ekib, W!karag/IIf(n.karag>0,N!karag,0.502) AS karag, z([nazar])+z([ibor])+z([berez])+z([per]) AS kan, d!nazar/IIf(n.nazar>0,N!nazar,0.484) AS nazar, d!ibor/IIf(n.ibor>0,N!ibor,0.537) AS ibor, d!berez/IIf(n.berez>0,N!berez,0.519) AS berez, d!per/IIf(n.per>0,N!per,0.537) AS per, z([azey])+z([cher]) AS irkut, d!azey/IIf(n.azey>0,N!azey,0.554) AS azey, d!cher/IIf(n.cher>0,N!cher,0.613) AS cher, W!hak/IIf(n.hak>0,N!hak,0.656) AS hak, W!tuv/IIf(n.tuv>0,N!tuv,0.781) AS tuv, z([gusin])+z([tugn]) AS bur, d!gusin/IIf(n.gusin>0,N!gusin,0.528) AS gusin, d!tugn/IIf(n.tugn>0,N!tugn,0.708) AS tugn, W!chit/IIf(n.chit>0,N!chit,0.434) AS chit, W!yakut/IIf(n.yakut>0,N!yakut,0.876) AS yakut, W!amur/IIf(n.amur>0,N!amur,0.38) AS amur, W!urg/IIf(n.urg>0,N!urg,0.645) AS urg, W!prim/IIf(n.prim>0,N!prim,0.388) AS prim, W!luch/IIf(n.luch>0,N!luch,0.256) AS luch, W!mag/IIf(n.mag>0,N!mag,0.64) AS mag, W!sah/IIf(N!sah>0,N!sah,0.596) AS sah, w.NUMB1120, c.ordnumb AS numb1, w.DEP, w.OES, w.ER, o.NAME AS oblname, w.VED, IIf(W!VED<3,1,2) AS вед, w.OBL, c.D, c.R, e.name AS oesname
FROM (((([Рабочий(станции)] AS w LEFT JOIN Натура99 AS n ON (w.NUMB1120=n.NUMB1120) AND (w.YEAR=n.YEAR)) LEFT JOIN [Рабочий(доп_угли)] AS d ON (w.NUMB1120=d.NUMB1120) AND (w.YEAR=d.YEAR)) INNER JOIN Имена_станций AS c ON w.NUMB1120=c.NUMB) INNER JOIN Имена_областей AS o ON w.OBL=o.OBL) INNER JOIN Имена_ОЭС AS e ON w.OES=e.oes
WHERE (((w.YEAR)>0) AND ((w.UGOL)>0));
